-- Generated by Murakumo for duckdb: the project as plain SQL, without dbt.
-- Every version of each row (an SCD2 snapshot), as dbt's check strategy keeps them.
CREATE TABLE IF NOT EXISTS snapshots.snp_dim_customer AS
SELECT customer_id, customer_name, phone, nation_name, market_segment, account_balance, CAST(NULL AS TIMESTAMP) AS dbt_valid_from, CAST(NULL AS TIMESTAMP) AS dbt_valid_to
FROM intermediate.int_dim_customer__versions
WHERE 1 = 0;
-- Close the current version of every row that changed.
UPDATE snapshots.snp_dim_customer SET dbt_valid_to = CAST(CURRENT_TIMESTAMP AS TIMESTAMP)
WHERE dbt_valid_to IS NULL
  AND EXISTS (SELECT 1 FROM intermediate.int_dim_customer__versions AS v WHERE v.customer_id = snapshots.snp_dim_customer.customer_id AND (v.customer_name IS DISTINCT FROM snapshots.snp_dim_customer.customer_name OR v.phone IS DISTINCT FROM snapshots.snp_dim_customer.phone OR v.nation_name IS DISTINCT FROM snapshots.snp_dim_customer.nation_name OR v.market_segment IS DISTINCT FROM snapshots.snp_dim_customer.market_segment OR v.account_balance IS DISTINCT FROM snapshots.snp_dim_customer.account_balance));
-- Add a current version for every row that is new or changed.
INSERT INTO snapshots.snp_dim_customer (customer_id, customer_name, phone, nation_name, market_segment, account_balance, dbt_valid_from, dbt_valid_to)
SELECT v.customer_id, v.customer_name, v.phone, v.nation_name, v.market_segment, v.account_balance, CAST(CURRENT_TIMESTAMP AS TIMESTAMP), CAST(NULL AS TIMESTAMP)
FROM intermediate.int_dim_customer__versions AS v
WHERE NOT EXISTS (SELECT 1 FROM snapshots.snp_dim_customer AS s WHERE s.customer_id = v.customer_id AND s.dbt_valid_to IS NULL);
